style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* kill Roblox’s background layers */
    html, body {
        background: none !important;
    }

    /* FORCE FULLSCREEN GIF LAYER */
    html::before {
        content: "";
        position: fixed;
        inset: 0;
        background-image: url("https://i.pinimg.com/originals/05/58/b2/0558b283c45a71db46cb969e8c82b2e3.gif");
        background-size: cover;
        background-position: center;
        background-repeat: no-repeat;
        z-index: 999999 !important;
        pointer-events: none;
    }

    /* push Roblox UI above it */
    body {
        position: relative;
        z-index: 0;
    }
}
